-- Squashed from 6 prior migrations (see git log) on 2026-05-04.
-- App: food-delivery. Generated by scripts/phase4-squash-app.mjs from a
-- pg_dump --schema-only of a freshly-migrated flagship_food_delivery DB.
--
-- This is a hand-derived baseline migration: it captures the verified-
-- green schema produced by the prior multi-file migration set, in a
-- single replayable file. `mlcl create <app>` will scaffold this as
-- migration 0010 and the runtime migration runner will apply it as a
-- single transaction at first boot.
CREATE TABLE public.addresses (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    label text,
    street text NOT NULL,
    city text,
    postal_code text,
    country text,
    lat double precision,
    lng double precision,
    is_default boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: delivery_tracking; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.delivery_tracking (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    order_id uuid NOT NULL,
    driver_id uuid,
    status text DEFAULT 'en_route'::text NOT NULL,
    driver_lat double precision,
    driver_lng double precision,
    eta_minutes integer,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


