    minimum_order integer DEFAULT 0 NOT NULL,
    estimated_delivery_min integer DEFAULT 30 NOT NULL,
    rating numeric(3,1) DEFAULT 0 NOT NULL,
    review_count integer DEFAULT 0 NOT NULL,
