--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.users (
    id uuid NOT NULL,
    "createdAt" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updatedAt" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    username character varying(255),
    name text,
    email character varying(1023),
    "twoFactorEnabled" boolean DEFAULT false,
    "oauthServer" text,
    "oauthId" text,
    "oauthData" jsonb,
    "planKey" text,
    "planExpiresAt" timestamp with time zone,
    "planAutoRenews" boolean DEFAULT false,
    -- Courier authorization. A plain authenticated session is NOT enough to
    -- read strangers' delivery addresses or claim/drive orders via the
    -- /api/delivery/* courier board — the caller must be a vetted courier.
    -- Opt-in / vetting is operator-controlled: a freshly self-registered
    -- account has is_courier = false and is therefore blocked by default
    -- (secure-by-default). The requireCourier middleware
    -- (src/middleware/require-courier.ts) lazily promotes accounts whose email
    -- is in the COURIER_EMAILS allow-list, making this column the durable
    -- source of truth thereafter.
    is_courier boolean DEFAULT false NOT NULL
);


